static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new NullPointerException("Target directory cannot be null");
    }
    if (name == null || name.isEmpty()) {
        throw new IllegalArgumentException("File name cannot be null or empty");
    }

    // Strip query parameters
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Reject absolute paths or paths that start with a separator
    if (Paths.get(name).isAbsolute() || name.startsWith("/") || name.startsWith("\\") || name.contains("..")) {
        throw new IllegalArgumentException("Invalid file name: " + name);
    }

    // Resolve and normalize the target path
    Path targetPath = dir.toPath().resolve(name).normalize();

    // Ensure the resolved path is still under the intended directory
    Path normalizedDir = dir.toPath().normalize();
    if (!targetPath.startsWith(normalizedDir)) {
        throw new IllegalArgumentException(
                "Attempt to create file outside of the target directory: " + name);
    }

    File file = targetPath.toFile();

    // Handle duplicate names
    int dot = name.lastIndexOf('.');
    String prefix = dot < 0 ? name : name.substring(0, dot);
    String suffix = dot < 0 ? "" : name.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
    }

    // Create parent directories if necessary
    file.getParentFile().mkdirs();

    return file;
}
