private static String normalizePath(final String path) {
    // Preserve null values – callers expect null to propagate.
    if (path == null) {
        return null;
    }

    // Empty strings are valid paths; return them unchanged to avoid
    // unintentionally converting an empty path to "/".
    if (path.isEmpty()) {
        return path;
    }

    // Count leading slashes.
    int leadingSlashCount = 0;
    while (leadingSlashCount < path.length()
            && path.charAt(leadingSlashCount) == '/') {
        leadingSlashCount++;
    }

    // Strip all leading slashes and then prepend a single one.
    String stripped = leadingSlashCount > 0
            ? path.substring(leadingSlashCount)
            : path;

    // Ensure the normalized path starts with exactly one slash.
    return '/' + stripped;
}
