private int extend(int v, final int t) {
    // Validate the number of bits. JPEG uses 1–16 bits for Huffman codes,
    // but we allow up to 31 to stay within int range.
    if (t <= 0 || t > 31) {
        throw new IllegalArgumentException("Bit length out of range: " + t);
    }

    // Threshold for determining whether the value is negative.
    final int threshold = 1 << (t - 1);

    // If v is less than the threshold, it represents a negative value
    // in the JPEG extended format. Adjust it accordingly.
    if (v < threshold) {
        // Use long arithmetic to avoid overflow when t == 31.
        final long mask = 1L << t;
        v -= (int) (mask - 1);
    }

    return v;
}
