/**
 * Utility class for extracting archive entries into a target directory.
 * <p>
 * The implementation has been hardened against path‑traversal attacks by
 * normalising entry names, validating that the resolved path stays within
 * the target directory, and using {@link Path} APIs for all file operations.
 */
public class Expander {

    // other methods

    /**
     * Extracts all readable entries from the supplied archive into the
     * specified target directory.
     *
     * @param supplier      provides the next {@link ArchiveEntry} to process
     * @param writer        writes the entry data to an {@link OutputStream}
     * @param targetDirectory the root directory where entries will be written
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical path of the target directory once
        Path canonicalTargetDir = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            // Reject absolute entry names – they would ignore the target directory
            Path entryPath = Paths.get(nextEntry.getName());
            if (entryPath.isAbsolute()) {
                throw new IOException("Entry name is absolute: " + nextEntry.getName());
            }

            // Resolve the entry against the target directory and normalise
            Path resolvedPath = canonicalTargetDir.resolve(entryPath).normalize();

            // Ensure the resolved path is still inside the target directory
            if (!resolvedPath.startsWith(canonicalTargetDir)) {
                throw new IOException("expanding " + nextEntry.getName()
                        + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist
                if (!Files.isDirectory(resolvedPath)) {
                    Files.createDirectories(resolvedPath);
                }
            } else {
                // Ensure parent directories exist
                Path parent = resolvedPath.getParent();
                if (parent != null && !Files.isDirectory(parent)) {
                    Files.createDirectories(parent);
                }

                // Write the file contents
                try (OutputStream out = Files.newOutputStream(resolvedPath,
                        StandardOpenOption.CREATE,
                        StandardOpenOption.TRUNCATE_EXISTING,
                        StandardOpenOption.WRITE)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods
}
