     * Securely obtains a {@link Document} or {@link InputSource} from the supplied body.
     * <p>
     * The method now parses XML strings and streams using a {@link DocumentBuilderFactory}
     * that is configured to disable external entity resolution and DTD loading, thereby
     * mitigating XXE attacks. If the body is already a {@link Document} or can be
     * converted via Camel's type converter, that value is returned unchanged.
     */
    @Override
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Class<?> type = getDocumentType();
        if (type == null) {
            // No conversion requested – return the body as-is
            return body;
        }

        Object answer = null;
        Exception conversionCause = null;

        // First try Camel's type converter
        try {
            answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
        } catch (Exception e) {
            conversionCause = e;
        }

