import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import javax.xml.transform.sax.SAXSource;
import javax.xml.transform.stream.StreamSource;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;
import org.apache.camel.Converter;
import org.apache.camel.Exchange;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import javax.xml.XMLConstants;

@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // other methods

    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else {
            inputSource = new InputSource(source.getInputStream());
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        XMLReader xmlReader = null;
        SAXParserFactory sfactory = null;

        try {
            // Prefer a factory supplied by the exchange, otherwise create a new one
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            // Enable secure processing
            try {
                sfactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            } catch (Exception e) {
                LOG.warn("SAXParserFactory does not support secure processing: {}", e.getMessage());
            }

            // Disable external entity resolution
            try {
                sfactory.setFeature("http://xml.org/sax/features/external-general-entities", false);
                sfactory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            } catch (Exception e) {
                LOG.warn("Failed to disable external entities on SAXParserFactory: {}", e.getMessage());
            }

            // Disallow DOCTYPE declarations
            try {
                sfactory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (Exception e) {
                LOG.warn("Failed to disallow DOCTYPE on SAXParserFactory: {}", e.getMessage());
            }

            sfactory.setNamespaceAware(true);

            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Additional safety: enforce disallow-doctype-decl on the XMLReader itself
            try {
                xmlReader.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (Exception e) {
                LOG.warn("Failed to disallow DOCTYPE on XMLReader: {}", e.getMessage());
            }

            // Disable loading external DTDs
            try {
                xmlReader.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            } catch (Exception e) {
                LOG.debug("XMLReader does not support disabling external DTD loading: {}", e.getMessage());
            }

        } catch (Exception ex) {
            LOG.warn("Cannot create the SAXParser XMLReader, due to {}", ex);
            // In case of failure, fall back to a minimal safe XMLReader
            try {
                SAXParserFactory fallbackFactory = SAXParserFactory.newInstance();
                fallbackFactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
                fallbackFactory.setNamespaceAware(true);
                SAXParser fallbackParser = fallbackFactory.newSAXParser();
                xmlReader = fallbackParser.getXMLReader();
            } catch (Exception fallbackEx) {
                LOG.error("Failed to create fallback XMLReader: {}", fallbackEx);
                throw new SAXException("Unable to create a secure XMLReader", fallbackEx);
            }
        }

        return new SAXSource(xmlReader, inputSource);
    }

    // other methods
}
