import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

/**
 * Utility class that determines whether a SCIM user self‑update request is allowed.
 *
 * <p>The original implementation performed field‑by‑field comparisons between the user
 * supplied in the request and the user retrieved from the database.  It did not verify
 * that the caller was actually the owner of the account being updated, allowing an
 * attacker to change another user’s email address.  The patched implementation adds
 * a strict ownership check using the authenticated principal and performs defensive
 * null handling to avoid NPEs.</p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private ScimUserProvisioning scimUserProvisioning;

    // -------------------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------------------

    /**
     * Determines whether the incoming HTTP request is allowed to modify the SCIM user
     * identified by the path variable.  The request is permitted only if:
     * <ul>
     *   <li>The authenticated principal matches the user ID in the URL.</li>
     *   <li>All mutable fields match the existing record (email, username, etc.).</li>
     * </ul>
     *
     * @param request the HTTP request containing the update payload
     * @return {@code true} if the update is allowed, {@code false} otherwise
     * @throws IOException if reading the request body fails
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1. Verify that the caller is authenticated and owns the account
        String authenticatedUserId = getAuthenticatedUserId(request);
        if (authenticatedUserId == null) {
            // No authenticated user – deny the request
            return false;
        }

        // 2. Extract the target user ID from the URL
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // 3. If the authenticated user does not own the account, reject
        if (!Objects.equals(authenticatedUserId, id)) {
            return false;
        }

        // 4. Retrieve the current user record from the database
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow creation (handled elsewhere)
            return true;
        }

        // 5. Parse the request body into a ScimUser object
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // 6. Perform field‑by‑field validation using Objects.equals to avoid NPEs
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // 7. All checks passed – allow the update
        return true;
    }

    // -------------------------------------------------------------------------
    // Helper Methods
    // -------------------------------------------------------------------------

    /**
     * Retrieves the authenticated user ID from the request.  The method first
     * attempts to obtain the principal name; if that is unavailable it falls back
     * to a request attribute that may be populated by an upstream filter.
     *
     * @param request the HTTP request
     * @return the authenticated user ID, or {@code null} if none is available
     */
    private String getAuthenticatedUserId(HttpServletRequest request) {
        Principal principal = request.getUserPrincipal();
        if (principal != null && principal.getName() != null) {
            return principal.getName();
        }
        // Fallback: some frameworks store the user ID in a request attribute
        Object attr = request.getAttribute("authenticatedUserId");
        return attr instanceof String ? (String) attr : null;
    }

    // other methods
}
